int cn_font_lookup(uint32_t codepoint)
{
    int lo = 0;
    int hi = cn_font_count - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (cn_font_codepoints[mid] == codepoint) return mid;
        if (cn_font_codepoints[mid] <  codepoint) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}
